# -*- coding: utf-8 -*-
"""Apply the adversarial verifier's fixes (V01–V54). Transactional: every anchor must match exactly once in its file,
otherwise nothing is written."""
import json, re, sys
SP = __import__("os").environ.get("SVA_WORKDIR", __import__("os").path.join(__import__("os").path.dirname(__import__("os").path.abspath(__file__)), "work"))
F = {k: f"{SP}/{v}" for k, v in dict(head="report_head.md", A="report_draft_A.md", B="report_draft_B.md", C="report_draft_C.md",
     D="report_draft_D.md", MED="report_var_DOM_MED.md", FILM="report_var_DOM_FILM.md", PPL="report_var_DOM_PPL.md",
     AUD="report_var_AUDIT2.md", EXT="report_var_EXTERNAL.md", TI="sva_report_tables_intent.py", T="sva_report_tables.py",
     ASM="sva_assemble_report.py", ASD="sva_assemble_domains.py", FIG="sva_figs.py", DMED="sva_dom_med.md", DEDU="sva_dom_edu.md").items()}
TXT = {k: open(p, encoding="utf-8").read() for k, p in F.items()}
errs = []
def sub(k, old, new):
    n = TXT[k].count(old)
    if n != 1: errs.append(f"{k}: {n}× {old[:60]}"); return
    TXT[k] = TXT[k].replace(old, new)
def line(k, anchor, new):
    lines = TXT[k].split("\n"); hits = [i for i, l in enumerate(lines) if anchor in l]
    if len(hits) != 1: errs.append(f"{k}: line-anchor {len(hits)}× {anchor[:60]}"); return
    lines[hits[0]] = new; TXT[k] = "\n".join(lines)
def append_line(k, anchor, suffix):
    lines = TXT[k].split("\n"); hits = [i for i, l in enumerate(lines) if anchor in l and suffix not in l]
    if len(hits) != 1: errs.append(f"{k}: append-anchor {len(hits)}× {anchor[:60]}"); return
    lines[hits[0]] = lines[hits[0]] + suffix; TXT[k] = "\n".join(lines)
def after_line(k, anchor, extra):
    lines = TXT[k].split("\n"); hits = [i for i, l in enumerate(lines) if anchor in l]
    if len(hits) != 1: errs.append(f"{k}: after-anchor {len(hits)}× {anchor[:60]}"); return
    ind = re.match(r"^\s*", lines[hits[0]]).group(0); lines.insert(hits[0] + 1, ind + extra); TXT[k] = "\n".join(lines)

